item(d,5,'Trong kiến trúc ViT–projector–LLM, vision encoder đảm nhiệm vai trò nào?', ['Biến ảnh thành biểu diễn/token thị giác','Trực tiếp xác nhận mọi fact cuối cùng là đúng','Chỉ chọn câu lệnh điều khiển robot không qua biểu diễn ảnh'],'a','Vision encoder trích đặc trưng ảnh; projector nối biểu diễn này vào không gian mà LLM xử lý.')
item(d,6,'Với cấu hình patch 16 px và merge 2×2, một nhóm 4 patch ban đầu thành bao nhiêu token sau merge?', ['1 token','4 tokens vì merge không đổi độ dài chuỗi','16 tokens vì nhân thêm hai trục'],'a','Merge không gian 2×2 gom bốn patch thành một token cho chuỗi đầu vào.',level='apply')
item(d,9,'Projector/connector trong VLM giải quyết nhu cầu nào?', ['Chuyển và có thể nén biểu diễn vision để đưa vào LLM','Thay hoàn toàn vision encoder bằng text tokenizer','Bảo đảm mọi object trong ảnh đều được grounding chính xác'],'a','Nó nối hai phần biểu diễn, nhưng không tự tạo bảo đảm về tính đúng nội dung.')
item(d,10,'Adapter-based multimodal training khác early fusion ở điểm nào?', ['Nối vision vào LLM đã pretrain text so với học chung modality từ đầu','Adapter chỉ dùng văn bản và không nhận ảnh ở inference','Early fusion bắt buộc là ghép boxes sau hai detectors'],'a','Đây là lựa chọn về cách tích hợp modality trong quá trình học, không phải sensor late fusion.')
item(d,11,'Vì sao token ảnh/video cần thông tin vị trí không gian và thời gian?', ['Để mô hình phân biệt vị trí h/w và quan hệ theo t trong chuỗi thị giác','Để mọi patch có cùng vị trí và bỏ cấu trúc ảnh','Để thay nội dung ảnh bằng một timestamp duy nhất'],'a','Token không chỉ có nội dung; cấu trúc vị trí giúp giữ quan hệ mà ảnh/video vốn có.')
item(d,12,'DeepStack bổ sung đặc trưng nhiều lớp ViT vào LLM có nhất thiết tăng số token ảnh trong chuỗi không?', ['Không; các đặc trưng được đưa vào lớp LLM qua mergers mà số token chuỗi giữ nguyên','Có; mỗi lớp ViT bắt buộc nối thêm một bản ảnh đầy đủ','Có; nó thay một token thành toàn bộ pixels gốc'],'a','Bổ sung thông tin qua các lớp khác với kéo dài chuỗi đầu vào.')
item(d,13,'Chèn timestamp cùng tokens của các frames video nhằm cung cấp loại ngữ cảnh nào?', ['Mốc thời gian để diễn giải diễn biến giữa các khung','Class label đúng của mọi vật trong frame','Bảo đảm mọi frame được quay ở cùng FPS thực tế'],'a','Thời gian là một phần của cấu trúc video; timestamp không thay nhãn hoặc nội dung.')
item(d,14,'Model trả box theo thang 0–1000 nhưng ảnh rộng W, cao H. Trước khi dùng box pixel cần làm gì?', ['Scale x theo W/1000 và y theo H/1000','Dùng nguyên số như pixel vì mọi VLM cùng convention','Chia cả x và y cho W bất kể chiều cao ảnh'],'a','Convention box phải được chuyển chính xác; cùng tên box không đồng nghĩa cùng hệ tọa độ.')
item(d,16,'Trong MoE, vì sao cần phân biệt total parameters và active parameters/token?', ['Bộ nhớ weights và lượng tính toán mỗi token phản ánh hai phạm vi khác nhau','Active parameters luôn bằng total nên không cần phân biệt','Total parameters chỉ là số tokens trong context'],'a','Routing kích hoạt một phần chuyên gia nhưng tổng weights vẫn ảnh hưởng yêu cầu lưu trữ/bộ nhớ.')
item(d,21,'RL với phần thưởng kiểm chứng được cần cơ sở nào để tạo reward?', ['Một verifier có thể kiểm đáp án hoặc điều kiện thành công','Chỉ lời tự nhận “tôi đúng” của policy','Chỉ độ dài reasoning bất kể kết quả'],'a','Reward lấy từ kiểm tra có thể xác minh, thay vì đồng nhất cách trình bày với tính đúng.')
item(d,22,'Những hướng can thiệp nào có thể giảm hallucination trong quá trình học VLM? (Chọn tất cả đáp án đúng.)',['Loại chi tiết không thật khi recaption','Lọc dữ liệu chất lượng kém trước SFT','Dùng reward cho nhiệm vụ thị giác kiểm chứng được','Coi output dài hơn là bằng chứng nhìn ảnh chính xác'],['a','b','c'],'Chất lượng dữ liệu và tín hiệu học có thể tác động nhiều điểm của pipeline, không chỉ inference prompt.')
item(d,26,'Một benchmark VLM công bố tốt nên được dùng thế nào trước auto-label dữ liệu riêng?', ['Làm đầu mối lựa chọn rồi thử trên domain, format và chi phí thực tế','Thay hoàn toàn validation trên dữ liệu cần gán','Chỉ chọn model lớn nhất bất kể box parser và điều kiện sử dụng'],'a','Độ phù hợp thực tế còn phụ thuộc dữ liệu, giao diện output và cost của pipeline.')
item(d,28,'VLM được dùng để tạo seed labels, tìm cảnh, duyệt nhãn và sinh reasoning traces. Nên đánh giá thế nào?', ['Đo riêng chất lượng cho từng vai trò','Dùng một điểm captioning để xác nhận tất cả vai trò','Coi việc có JSON hợp lệ chứng minh tất cả nhãn đúng'],'a','Các công việc có mục tiêu và loại lỗi khác nhau nên không thể dùng một phép đo thay mọi kiểm chứng.')
item(d,30,'Schema cho phép một trường giá trị là null giúp xử lý tình huống nào?', ['Không đủ thông tin để trả giá trị mà không cần bịa một số hợp lệ','Tự xác nhận mọi số khác null đều đúng','Bỏ qua mọi value validation vì schema đã hợp lệ'],'a','Cho phép không biết giảm áp lực điền dữ kiện giả; app vẫn cần kiểm giá trị và ngữ nghĩa.')
item(d,34,'Caption VLM mâu thuẫn inventory detector nên được xử lý theo hướng nào?', ['Đưa vào kiểm tra/bất đồng thay vì tự chấp nhận caption','Coi VLM luôn đúng vì sinh được lời giải thích','Coi detector luôn đúng rồi xóa mọi case khác biệt không audit'],'a','Hai nguồn đều có thể sai; bất đồng là tín hiệu để định tuyến kiểm chứng, không phải kết luận tự động.')
item(d,40,'Flow/diffusion action head khác giải mã action tokens rời rạc ở điểm nào?', ['Tinh chỉnh/khử nhiễu cả chuỗi quỹ đạo thay vì sinh từng token tuần tự','Chỉ chọn một nhãn hữu hạn không thể tạo quỹ đạo','Chỉ tạo caption về hành động thay vì điều khiển'],'a','Hai họ biểu diễn và sinh hành động theo cơ chế khác nhau; flow head hướng tới chuỗi liên tục mượt.')
