item(d,7,'Synthetic data nên được xem như bổ sung dữ liệu thật theo nguyên tắc nào?', ['Lấp vùng dữ liệu khó có, còn phán quyết cuối dùng test thật độc lập','Thay toàn bộ test thật bằng dữ liệu cùng generator','Cứ giống ảnh thật là có thể bỏ mọi đánh giá domain thật'],'a','Generator có phân bố riêng, nên hiệu quả ngoài đời phải được kiểm trên dữ liệu không phụ thuộc nó.')
item(d,10,'Những nhãn nào simulator có thể cung cấp trực tiếp từ trạng thái cảnh? (Chọn tất cả đáp án đúng.)',['Depth theo pixel','Optical/scene flow','Vận tốc và masks từ trạng thái mô phỏng','Mọi quy ước class nghiệp vụ tự được xác định không cần đặc tả'],['a','b','c'],'Thông tin hình học/trạng thái đã biết giúp tạo labels khó gán thủ công; ontology vẫn cần xác định.')
item(d,17,'Mở rộng ngẫu nhiên hóa nhiều tham số với cùng ngân sách mẫu có rủi ro gì?', ['Không gian phình lớn làm mẫu hữu ích gần điều kiện thật trở nên thưa','Mỗi chiều mới tự tăng mật độ mẫu ở mọi vùng','Chỉ cần điều kiện thật nằm trong biên là đã đủ coverage dày'],'a','Bao phủ biên không đồng nghĩa đủ mật độ; chiều cao hơn cần thiết kế sampling có chủ đích.')
