item(d,20,'Khi mô phỏng LiDAR mất tia, vì sao chỉ khớp tổng số điểm rơi có thể chưa đủ?', ['Vị trí và cấu trúc mất tia ảnh hưởng thông tin vật thể','Mọi pattern mất cùng số điểm đều tương đương','Chỉ ảnh camera mới bị ảnh hưởng bởi cấu trúc missing data'],'a','Sensor gap nằm cả ở cách dữ liệu mất, không chỉ số lượng điểm còn lại.')
item(d,25,'Real2Sim chỉ replay tracks cố định có giới hạn nào khi ego đổi đường?', ['Các tác nhân khác không tự phản ứng với hành động mới của ego','Mọi actor tự có policy tương tác do có track log','Ảnh mới không còn phụ thuộc geometry của cảnh'],'a','Tái dựng cảnh và sinh góc nhìn khác không tự tạo mô hình hành vi phản ứng.')
item(d,26,'NeRF và Gaussian Splatting lưu/hiển thị cảnh theo hai cơ chế nào?', ['NeRF truy vấn trường qua mạng dọc tia; splatting raster hóa Gaussian tường minh','Cả hai chỉ sao chép ảnh gần nhất không có biểu diễn 3D','NeRF chỉ là box annotations còn splatting chỉ là class labels'],'a','Cách biểu diễn implicit hay explicit dẫn tới đánh đổi rendering và lưu thông tin.')
item(d,28,'Camera mới lệch xa quỹ đạo đã ghi có thể làm novel-view rendering kém vì sao?', ['Một số bề mặt/góc nhìn chưa từng được quan sát đầy đủ','Tăng khoảng cách tới log luôn tạo thêm dữ liệu thực cho model','Mọi góc nhìn đều đã được xác định duy nhất từ một ảnh'],'a','Disocclusion và thiếu quan sát giới hạn tính tin cậy của tái dựng ở các góc mới.')
item(d,35,'Sinh ảnh có điều kiện từ box/map/calibration đặt yêu cầu kiểm tra quan trọng nào?', ['Ảnh sinh có thực sự tuân thủ các labels điều kiện không','Chỉ labels tồn tại trước ảnh là đủ chứng minh đúng','Chỉ ảnh có độ phân giải cao là đủ xác nhận hình học'],'a','Có nhãn trước không bảo đảm generator đặt đúng vật, vị trí và cấu trúc tương ứng.')
item(d,39,'Vì sao FID đẹp chưa chứng minh synthetic labels phù hợp để train detector?', ['Metric phân bố hình ảnh không trực tiếp xác nhận box/label alignment','FID đo chính xác IoU của mọi box trong ảnh','Ảnh giống thật luôn có đúng tất cả nhãn điều kiện'],'a','Cần kiểm nhãn và downstream performance trên real test, ngoài chất lượng hình ảnh.')
item(d,40,'Đánh giá dữ liệu sinh nên báo theo target slices và cả slices cần giữ để làm gì?', ['Nhận diện lợi ích đúng vùng cùng regression ở vùng khác','Chỉ chọn slice tăng mạnh nhất để kết luận tổng quát','Trộn mọi điều kiện thành average để che khác biệt'],'a','Bổ sung cho tình huống hiếm có thể ảnh hưởng nơi khác; đánh giá cần nhìn cả lợi ích và tổn hại.')
item(d,45,'Một ID switch trong dữ liệu quỹ đạo có thể dạy forecasting điều sai nào?', ['Vật biến mất/xuất hiện hoặc quỹ đạo bị cắt thay vì liên tục','Chỉ thay tên file mà không ảnh hưởng mẫu học','Tự tạo thêm ground-truth tương lai chính xác'],'a','Lỗi association trở thành cấu trúc sai trong mẫu trajectory, cần nối và kiểm offline.')
item(d,46,'Tính gia tốc bằng sai phân hai lần trên box vị trí nhiễu có rủi ro gì?', ['Khuếch đại nhiễu thành gia tốc giả lớn','Tự loại hết jitter vì đạo hàm làm mượt','Không phụ thuộc sampling interval'],'a','Đạo hàm số nhạy với noise và khoảng thời gian; cần smoothing và kiểm tính khả thi.')
item(d,49,'Những checks nào hỗ trợ phát hiện quỹ đạo không khả thi? (Chọn tất cả đáp án đúng.)',['Gia tốc/jerk','Độ cong và gia tốc ngang','Tính liên tục và vị trí trong vùng chạy được','Chỉ số frames đủ dài bất kể chuyển động'],['a','b','c'],'Nhiều phép kiểm bắt các lỗi khác nhau: jitter, nối nhầm ID, hướng lật, calibration hay pose sai.')
item(d,66,'Automatic Domain Randomization điều chỉnh vùng tham số theo nguyên tắc nào?', ['Nới khi policy làm tốt, thu khi khó vượt khả năng hiện tại','Luôn dùng range rộng nhất ngay từ đầu','Giữ mọi tham số cố định dù policy đã học vững'],'a','ADR điều chỉnh độ khó theo khả năng thay vì ngẫu nhiên hóa vô hạn hoặc không đổi.')
d='p2-t4-d12'
item(d,11,'Log nhiều sensor cần giữ chung điều gì để replay có ý nghĩa?', ['Trục thời gian và timestamps dù mỗi sensor có nhịp riêng','Chỉ thứ tự files theo tên để coi là đồng thời','Chỉ một FPS cố định thay cho mọi sensor clocks'],'a','Temporal alignment là nền để dựng lại chuỗi dữ liệu đúng lúc.')
item(d,12,'Replay raw sensor và replay output perception có đánh đổi nào?', ['Raw sát pipeline đầy đủ hơn; output perception cô lập phần sau và thường nhẹ hơn','Output perception luôn kiểm tra được detector mới như raw sensor','Mọi mức replay đi qua cùng khối phần mềm nên không khác cost'],'a','Điểm chèn dữ liệu quyết định khối nào được thực sự thử và khả năng cô lập lỗi.')
item(d,16,'Khi đổi duy nhất perception block, vì sao cần so theo slices như đêm/mưa/occlusion?', ['Average có thể che một điều kiện xấu đi dù tổng tăng','Mọi slice phải tăng cùng mức nếu average tăng','Chỉ cần kiểm điều kiện dễ để ước lượng mọi failure mode'],'a','Giữ cùng log và phân tích lát cắt giúp quy khác biệt về thay đổi và vùng bị ảnh hưởng.')
item(d,18,'Replay kho log cũ sau mỗi thay đổi code phục vụ mục tiêu gì?', ['Phát hiện regression so với kết quả chuẩn đã biết','Thay toàn bộ đánh giá hành động mới trong thế giới phản ứng','Chứng minh hệ thống chưa từng gặp failure ngoài log'],'a','Regression replay kiểm tính ổn định trên lịch sử; phạm vi bằng chứng vẫn bị giới hạn bởi các logs đó.')
item(d,19,'Những yếu tố nào có thể làm replay khác nhau một lượng số nhỏ? (Chọn tất cả đáp án đúng.)',['Thứ tự cộng số thực','Đa luồng/thứ tự messages','GPU kernels','Chỉ việc tên experiment khác trong báo cáo'],['a','b','c'],'Thực thi số và song song có thể tạo nondeterminism cần kiểm soát/đặt dung sai phù hợp.')
item(d,22,'Vì sao replay “nhanh nhất có thể” có thể bỏ sót deadline misses?', ['Nó có thể chờ xử lý xong mới cấp frame sau, không tái tạo hạn thời gian thật','Tăng tốc luôn làm mọi lỗi latency nghiêm trọng hơn nên không thể bỏ sót','Deadline chỉ tồn tại khi dùng dữ liệu tổng hợp'],'a','Kiểm timing cần chạy theo timestamps/rate thực để thấy backlog và trễ hạn.')
item(d,24,'Log replay phù hợp nhất để kiểm gì trước khi chạy thực?', ['Perception trên dữ liệu đã xảy ra và lỗi phần mềm trong pipeline','Mọi phản ứng của thế giới với hành động ego chưa từng thực hiện','Bảo đảm an toàn với mọi kịch bản chưa quan sát'],'a','Thế giới ghi sẵn không thay đổi theo hành động mới, nên phạm vi replay cần được hiểu rõ.')
item(d,29,'Model giữ vận tốc hiện tại có thể có open-loop score cao khi nào?', ['Dataset chủ yếu chứa cảnh đi thẳng ít thay đổi','Nó đã chứng minh xử lý mọi tương tác khó','Open-loop metric tự cân bằng mọi maneuver hiếm'],'a','Dữ liệu nhiều cảnh dễ có thể thưởng baseline đơn giản; cần kiểm slices và hành vi khó.')
item(d,31,'mAP tăng cần được nối với closed-loop evaluation vì sao?', ['Cải thiện perception metric chưa chắc cải thiện hành vi toàn hệ thống','mAP là tỷ lệ va chạm nên đã đủ cho release','Mọi lỗi perception có tác động planner giống nhau'],'a','Metric thành phần và mục tiêu hệ thống có thể không biến đổi cùng chiều.')
item(d,32,'So mô hình học với bộ luật đơn giản trong closed loop giúp quyết định điều gì?', ['Mô hình mới có đem lợi ích vượt baseline đủ để thay thế không','Chỉ số tham số model có lớn hơn rule code không','Có thể bỏ mọi test khác nếu model phức tạp hơn'],'a','Độ phức tạp không tự là giá trị; baseline xác định mức tối thiểu phải vượt ở task thực.')
item(d,34,'Cùng phần mềm/bản đồ nhưng kết quả closed-loop biến động do noise. Nên làm gì?', ['Chạy lặp nhiều lần và báo biến động thay vì chọn một lần đẹp','Chỉ giữ lần thành công để loại nhiễu khỏi báo cáo','Kết luận mọi thất bại là do model ngay từ một seed'],'a','Một lần chạy không mô tả đủ độ ổn định của hệ thống stochastic.')
item(d,35,'Điểm hoàn thành route cao vẫn có thể bị giảm mạnh bởi điều gì?', ['Các vi phạm và mức phạt trong scoring','Việc route được đo bằng khoảng cách thay vì tên map','Chỉ số lượng sensors dù không có vi phạm'],'a','Completion cần đi cùng tuân thủ; đi hết nhưng vi phạm không đồng nghĩa hành vi tốt.')
item(d,39,'Kịch bản logic và kịch bản cụ thể khác nhau thế nào?', ['Logic quy định khoảng tham số; cụ thể chọn giá trị để chạy ngay','Logic chỉ là một log file còn cụ thể chỉ là mô tả bằng lời','Cả hai đều bắt buộc một giá trị cố định cho mọi điều kiện'],'a','Từ mô tả chức năng đi tới ranges rồi instances giúp sinh cả họ test cases.')
item(d,41,'Từ một ca cắt làn gây lỗi, mở rộng thành test family nên làm gì?', ['Tham số hóa và quét quanh khoảng cách/tốc độ để tìm boundary','Sao chép cùng ca nhiều lần chỉ đổi tên','Chỉ test một điểm trung bình dễ pass'],'a','Ranh giới failure cho biết độ bền của giải pháp, hơn việc ghi nhớ đúng một instance.')
item(d,51,'Vì sao hai bộ cùng 24 scenarios có thể có coverage khác nhau?', ['Một bộ có thể tập trung cùng góc ODD, bộ kia trải các điều kiện quan trọng','Cùng số scenarios luôn bao phủ cùng không gian','Coverage chỉ phụ thuộc tổng số frames, không cần xét vùng tham số'],'a','Cần xem vùng tham số/điều kiện đã thử, không chỉ đếm files.')
item(d,54,'Xe trong log tiếp tục chạy đường cũ dù ego mới đã phanh, tạo va chạm không thực tế. Cần lớp kiểm thử nào bổ sung?', ['Tác nhân có phản ứng với ego','Chỉ replay cùng log nhanh hơn','Chỉ giảm dung sai số học của replay'],'a','Reactive agents cho thế giới đáp lại hành động mới, giảm kết luận giả từ quỹ đạo đóng băng.')
